// ============================================================
// LANGUAGE HANDLER: Process Language Selection (v3.0 - FIXED)
// ============================================================

const context = $json;
const text = (context.user_message || '').toLowerCase();
const callbackData = context.callback_data || '';

// Объявляем переменные ПРАВИЛЬНО
let language = 'ru';
let confirmation = '';

// Проверяем callback_data СНАЧАЛА (inline-кнопки), потом текст
if (callbackData === 'lang_ru' || text.includes('русский') || text.includes('русск')) {
  language = 'ru';
  confirmation = 'Отлично! Продолжим на русском. 🇷🇺';
} else if (callbackData === 'lang_ky' || text.includes('кыргыз') || text.includes('kyrgyz')) {
  language = 'ky';
  confirmation = 'Жакшы! Мен сиз менен кыргызча сүйлөшөм. 🇰🇬';
} else if (callbackData === 'lang_uz' || text.includes('узбек') || text.includes("o'zbek") || text.includes('ozbek')) {
  language = 'uz';
  confirmation = "Yaxshi! Men siz bilan o'zbekcha gaplashaman. 🇺🇿";
} else if (callbackData === 'lang_tg' || text.includes('таджик') || text.includes('тоҷик') || text.includes('tojik')) {
  language = 'tg';
  confirmation = 'Хуб! Ман бо шумо тоҷикӣ гап мезанам. 🇹🇯';
} else {
  // Fallback на русский
  language = 'ru';
  confirmation = 'Продолжим на русском. 🇷🇺';
}

// Формируем сообщение с вопросом об имени
const responseMessage = confirmation + '\n\n🤝 Расскажите, пожалуйста, как вас зовут?';

return {
  // Context passthrough
  user_id: context.user_id,
  chat_id: context.chat_id,
  session_id: context.session_id,
  user_message: context.user_message,
  known_data: context.known_data || {},
  route_category: context.route_category,

  // Response
  response_message: responseMessage,
  final_message: responseMessage,
  extracted_data: context.known_data || {},
  interview_complete: false,
  show_language_buttons: false,
  needs_escalation: false,

  // Updated language
  language: language,
  selected_language: language
};
